using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace MoreSpace {
class CacheArea {public string Name,Path,Process;}
static class CacheCatalog {
 public static List<CacheArea> Areas(){string local=Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),roam=Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);var list=new List<CacheArea>{new CacheArea{Name="Relatórios de falha",Path=Path.Combine(local,"CrashDumps")},new CacheArea{Name="npm • cache",Path=Path.Combine(local,"npm-cache","_cacache"),Process="node"},new CacheArea{Name="VS Code • Cache",Path=Path.Combine(roam,"Code","Cache"),Process="Code"},new CacheArea{Name="VS Code • CachedData",Path=Path.Combine(roam,"Code","CachedData"),Process="Code"}};
  foreach(var browser in new[]{new[]{"Chrome","Google\\Chrome\\User Data","chrome"},new[]{"Edge","Microsoft\\Edge\\User Data","msedge"}}){var root=Path.Combine(local,browser[1]);if(!Directory.Exists(root))continue;foreach(var profile in Directory.GetDirectories(root).Where(p=>Path.GetFileName(p)=="Default"||Path.GetFileName(p).StartsWith("Profile ")))foreach(var cache in new[]{"Cache","Code Cache","GPUCache"})list.Add(new CacheArea{Name=browser[0]+" • "+Path.GetFileName(profile)+" • "+cache,Path=Path.Combine(profile,cache),Process=browser[2]});}return list.Where(a=>Directory.Exists(a.Path)).ToList();}
 public static bool Running(CacheArea area){if(String.IsNullOrEmpty(area.Process))return false;var processes=Process.GetProcessesByName(area.Process);try{return processes.Length>0;}finally{foreach(var p in processes)p.Dispose();}}
}
partial class MainWindow {
 ListView cacheAreas=new SmoothListView();Label cacheNote=new Label();
 void SetupAdvancedCleanup(){var page=Page("Caches","Categorias conhecidas de cache e relatórios. Apps abertos ficam bloqueados. Só arquivos sem alteração/acesso há 7 dias são oferecidos; histórico, cookies e senhas não entram.");var bar=new FlowLayoutPanel{Dock=DockStyle.Fill};bar.Controls.Add(Btn("Encontrar categorias",delegate{if(busy||demoMode)return;cacheAreas.Items.Clear();try{foreach(var area in CacheCatalog.Areas()){bool running=CacheCatalog.Running(area);var row=new ListViewItem(new[]{area.Name,running?"Feche o aplicativo":"Disponível para análise",area.Path});row.Tag=area;if(running)row.ForeColor=Color.Gray;cacheAreas.Items.Add(row);}}catch(Exception ex){MessageBox.Show(this,ex.Message);}}));bar.Controls.Add(Btn("Analisar categoria…",async delegate{await CleanCacheArea();}));bar.Controls.Add(Btn("Cancelar análise",delegate{if(cts!=null)cts.Cancel();}));page.Controls.Add(bar,0,1);cacheAreas.Dock=DockStyle.Fill;cacheAreas.View=View.Details;cacheAreas.FullRowSelect=true;cacheAreas.MultiSelect=false;cacheAreas.Columns.Add("Categoria",270);cacheAreas.Columns.Add("Estado",200);cacheAreas.Columns.Add("Caminho",500);page.Controls.Add(cacheAreas,0,2);cacheNote.Dock=DockStyle.Fill;cacheNote.Text="A limpeza é revisada por arquivo. Caches podem ser recriados e precisam ser baixados novamente.";page.Controls.Add(cacheNote,0,3);}
 async Task CleanCacheArea(){if(busy||demoMode||cacheAreas.SelectedItems.Count==0)return;var area=(CacheArea)cacheAreas.SelectedItems[0].Tag;if(CacheCatalog.Running(area)){MessageBox.Show(this,"Feche o aplicativo antes de analisar o cache.");return;}Busy(true);cts=new CancellationTokenSource();try{var errors=new List<string>();var entries=await Task.Run(()=>Engine.Scan(new[]{area.Path},true,cts.Token,(n,p)=>{},errors));cacheNote.Text=entries.Count+" arquivos antigos • "+errors.Count+" falhas de acesso";using(var dialog=new ChartFileDialog(null,entries)){if(dialog.ShowDialog(this)!=DialogResult.OK)return;if(CacheCatalog.Running(area)){MessageBox.Show(this,"O aplicativo foi aberto. Limpeza cancelada.");return;}int count=0;long bytes=0;var before=SavingsStore.Snapshot();bool permanent=dialog.Permanent;foreach(var e in dialog.Selection)try{if(CacheCatalog.Running(area))break;await Task.Run(()=>{if(!Engine.Under(e.Path,area.Path))throw new IOException("Arquivo fora do cache.");ChartFileRules.Validate(e,Path.GetDirectoryName(e.Path));FileRemoval.Delete(e.Path,permanent);});count++;bytes+=e.Size;Log("CACHE REMOVIDO "+e.Path);}catch(Exception ex){Log("CACHE PRESERVADO "+e.Path+": "+ex.Message);}if(count>0)RecordSavings(permanent?"Caches":"Via Lixeira (cache)",count,permanent?(long?)bytes:null,before);cacheNote.Text=count+" arquivos processados • "+Engine.Bytes(bytes)+" lógicos. Falhas em Atividade.";}}catch(OperationCanceledException){cacheNote.Text="Análise cancelada.";}catch(Exception ex){MessageBox.Show(this,ex.Message);}finally{cts.Dispose();cts=null;Busy(false);}}
}
}
